let vacante = $json.vacante;
vacante = (vacante === undefined || vacante === null || vacante === '') ? null : String(vacante).trim();
if (vacante !== null && vacante.length > 200) throw new Error('BOT_TOOL_INVALID_INPUT: valor de vacante demasiado largo');
return [{ json: { vacante } }];
